import { json, okOptions } from "../_shared/cors.ts";

function deriveMonthKey(dateFrom: string, dateTo: string) {
  const candidate = (dateTo || dateFrom || "").trim();
  const match = candidate.match(/^(\d{4}-\d{2})/);
  if (!match) {
    throw new Error("Could not derive month_key from date range");
  }
  return match[1];
}

Deno.serve(async (req) => {
  const options = okOptions(req);
  if (options) return options;
  if (req.method !== "POST") return json({ ok: false, error: "Method not allowed" }, { status: 405 });

  try {
    const payload = normalizeRequest(await req.json());
    const supabase = adminClient();
    const row = {
      month_key: deriveMonthKey(payload.date_from, payload.date_to),
      requested_by: payload.requested_by,
      runner_type: "supabase_edge",
      model_name: payload.model_name,
      date_from: payload.date_from,
      date_to: payload.date_to,
      index_scope: payload.index_scope,
      request_payload: payload,
      status: "queued",
      summary: {
        mode: payload.mode,
        advisory_only: true,
      },
    };
    const { data, error } = await supabase
      .from("evaluator_jobs")
      .insert(row)
      .select("job_id,status,request_payload,proposal_count,created_at,updated_at")
      .single();
    if (error) throw error;
    return json({
      ok: true,
      ...data,
      message: "Evaluator job queued in advisory-only mode.",
    });
  } catch (error) {
    return json({ ok: false, error: error.message || String(error) }, { status: 400 });
  }
});

import { createClient } from "https://esm.sh/@supabase/supabase-js@2";

export function adminClient() {
  const url = Deno.env.get("SUPABASE_URL");
  const key = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY");
  if (!url || !key) {
    throw new Error("Missing SUPABASE_URL or SUPABASE_SERVICE_ROLE_KEY");
  }
  return createClient(url, key, {
    auth: { persistSession: false, autoRefreshToken: false },
  });
}

export type EvaluationJobStatus =
  | "queued"
  | "running"
  | "completed"
  | "failed"
  | "cancelled";

export interface EvaluationJobRequest {
  date_from: string;
  date_to: string;
  index_scope?: string[];
  mode?: string;
  requested_by?: string;
  model_name?: string;
}

export function normalizeIndexScope(raw: unknown): string[] {
  const arr = Array.isArray(raw) ? raw : [];
  const cleaned = arr
    .map((v) => String(v || "").trim().toUpperCase())
    .filter((v) => v === "BNF" || v === "NF");
  return cleaned.length ? Array.from(new Set(cleaned)) : ["BNF", "NF"];
}

export function normalizeRequest(payload: Partial<EvaluationJobRequest>): EvaluationJobRequest {
  const dateFrom = String(payload.date_from || "").trim();
  const dateTo = String(payload.date_to || "").trim();
  if (!dateFrom || !dateTo) {
    throw new Error("date_from and date_to are required");
  }
  return {
    date_from: dateFrom,
    date_to: dateTo,
    index_scope: normalizeIndexScope(payload.index_scope),
    mode: String(payload.mode || "manual_advisory"),
    requested_by: String(payload.requested_by || "market_radar_app"),
    model_name: String(payload.model_name || "gemini-2.5-pro"),
  };
}

export const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
  "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
};

export function json(body: unknown, init: ResponseInit = {}) {
  return new Response(JSON.stringify(body), {
    ...init,
    headers: {
      "Content-Type": "application/json",
      ...corsHeaders,
      ...(init.headers || {}),
    },
  });
}

export function okOptions(req: Request) {
  if (req.method === "OPTIONS") {
    return new Response("ok", { headers: corsHeaders });
  }
  return null;
}

